<?php get_header(); ?><main id="main-content" class="bh-main"><?php get_template_part('template-parts/hero',null,array('title'=>get_the_archive_title(),'text'=>get_the_archive_description())); ?><section class="bh-wrap bh-results"><?php if(have_posts()): ?><div class="bh-grid"><?php while(have_posts()): the_post(); ?><article class="bh-card bh-list-card"><?php if(has_post_thumbnail()): the_post_thumbnail('medium_large'); endif; ?><div class="bh-card__body"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?><a class="bh-text-link" href="<?php the_permalink(); ?>"><?php esc_html_e('View details','bubba-hub'); ?> →</a></div></article><?php endwhile; ?></div><?php the_posts_pagination(); ?><?php else: ?><div class="bh-card bh-empty"><?php esc_html_e('Nothing found here yet.','bubba-hub'); ?></div><?php endif; ?></section></main><?php get_footer(); ?>